parameters.outputSchema:
{
  "type": "object",
  "required": ["action", "strategy", "entry_stage", "reasoning"],
  "properties": {
    "action": { "enum": ["continue", "stop"] },
    "strategy": { "type": "string", "description": "Free-form instruction the prompt rewriter will follow. Be specific about WHAT to change and WHY. Empty string when action='stop'." },
    "entry_stage": { "enum": ["smoke", "quick", "full"], "description": "Where to start the candidate's evaluation. smoke=10 random; quick=100 stratified; full=whole dataset (real candidate). Use 'smoke' on iter 0 and for risky edits." },
    "reasoning": { "type": "string", "description": "One sentence on why this action / strategy / stage." },
    "target_confusion_pair": { "type": "string", "description": "If strategy targets a specific gt->pred pair, name it. Empty string when none." }
  }
}

